-- Initial "Mejoras" for JPMG (slug 'john'): what already reached the office, as drafts
-- for Lumar to review and publish from the panel. Inserts nothing where that organization doesn't exist.
INSERT INTO `Improvement` (`title`, `summary`, `beforeText`, `afterText`, `example`, `area`, `releasedOn`, `publishedAt`, `createdAt`, `updatedAt`, `producerId`)
SELECT 'Nueva sección Mejoras', 'Acá vamos a ir contando cada cambio que hacemos en el bot y en el panel, explicado con ejemplos.', NULL, 'Cada mejora dice qué pasaba antes, qué pasa ahora y, cuando sirve, un ejemplo de conversación. Las que todavía no viste aparecen marcadas como nuevas y el menú muestra cuántas hay.', NULL, 'PANEL', '2026-10-12', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'El bot responde lo que le piden desde el primer mensaje', 'Si el cliente arranca pidiendo algo concreto, el bot va directo a eso en vez de presentarse y preguntar si ya es cliente.', 'Ante cualquier primer mensaje el bot contestaba "Soy NICO… ¿ya sos cliente?", aunque el cliente ya hubiera pedido la póliza o una cotización. Más de la mitad de esas presentaciones caían sobre mensajes con un pedido concreto.', 'El bot entiende qué pide el primer mensaje: si es la póliza o un comprobante, pide el DNI o la patente; si quiere cotizar, abre directamente las opciones de cotización. La pregunta "¿ya sos cliente?" queda solo para los saludos sueltos.', 'Cliente: Hola, me pasás mi póliza
NICO: ¡Hola! Soy NICO 👋 Para acceder a tus datos necesito identificarte. Pasame el DNI del titular o la patente del vehículo asegurado.', 'BOT', '2026-10-09', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'El bot no interrumpe cuando alguien de la oficina está atendiendo', 'Cuando alguien de la oficina responde un chat desde el celular, el chat queda en sus manos mientras el cliente siga hablando.', 'A los 30 minutos el chat volvía solo al bot aunque el cliente siguiera conversando con la oficina, y el bot podía saludar con el menú ante un simple "gracias".', 'El chat sigue con la persona mientras haya conversación. Vuelve al bot recién después de 2 horas sin mensajes o al terminar el horario de atención. Y si el cliente cierra con "gracias" o "dale" una charla que tuvo con una persona, el bot no contesta.', 'Oficina: Ahí te envié todo. ¡Buen finde!
Cliente: Gracias a usted
(El bot no responde: el chat sigue con la oficina.)', 'BOT', '2026-10-08', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'El bot entiende los audios', 'Los audios de los clientes se transcriben: el bot los responde como si fueran texto y en la Bandeja se pueden escuchar junto con la transcripción.', 'El bot no podía responder audios y en la Bandeja no se veía qué decían.', 'El bot pasa el audio a texto y responde lo que el cliente pidió. En la Bandeja aparece el audio para escucharlo y, debajo, el texto.', 'Cliente: (audio) "Quiero cotizar una Kymco Skytown 150, año 2026, código postal 2000"
NICO: La moto quedó identificada como KYMCO SKYTOWN 150, 2026 (CP 2000). Suma asegurada: $ 5.990.000…', 'BOT', '2026-10-05', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Reconoce el DNI o la patente aunque vengan dentro de una frase', 'El bot identifica al cliente aunque el DNI venga con el nombre, separado con espacios o dicho en un audio.', 'Si el DNI no venía solo, el bot podía no reconocerlo y volver a pedirlo.', 'El bot encuentra el DNI o la patente dentro del mensaje, venga como venga.', 'Cliente: Bernachea Eduardo Miguel KBE 396
NICO: ✅ ¡Listo, te identifiqué! Contame, ¿en qué te doy una mano hoy?', 'BOT', '2026-10-05', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Denuncia de siniestro en un solo mensaje', 'Para denunciar un siniestro el bot pide todos los datos juntos y entiende lo que el cliente escribe, en vez de hacer una pregunta por vez.', 'El bot hacía una pregunta por cada dato de la denuncia, y la conversación se hacía larga.', 'El bot manda la lista de datos que necesita en un solo mensaje y lee la respuesta del cliente. Si falta algún dato obligatorio, vuelve a preguntar solo ese.', NULL, 'BOT', '2026-10-05', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Cotizaciones con suma asegurada y precio con tarjeta y en efectivo', 'Cada cotización muestra la suma asegurada y, para cada cobertura, el precio con tarjeta y en efectivo. La cobertura recomendada para el año del vehículo aparece primero.', 'La cotización mostraba un solo precio por cobertura y sin la suma asegurada.', 'Se ve la suma asegurada del vehículo y los dos precios de cada cobertura, ordenadas con la recomendada arriba.', 'NICO: Suma asegurada: $ 3.307.000
• A — Responsabilidad civil: con tarjeta $ 21.339 | en efectivo $ 22.488
• B1 — RC + incendio + robo: con tarjeta $ 61.114 | en efectivo $ 64.667', 'COTIZADOR', '2026-10-05', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Motos cotizadas como las ofrece Triunfo, también 0 km', 'Las motos se cotizan con las coberturas A, B4 y B1 de Triunfo, con textos pensados para motos, y ahora también se pueden cotizar modelos que solo existen como 0 km.', 'Las motos usaban los textos de las coberturas de auto, y los modelos nuevos que el catálogo solo lista como 0 km no se podían cotizar.', 'Cada cobertura de moto explica qué incluye y qué no, y una moto 0 km del año se cotiza normalmente.', 'Cliente: Zanella ZR 200 enduro 2026 Rosario 2000
NICO: Cotización orientativa para tu Zanella ZR 200, modelo 2026, en Rosario…
Cliente: B1
NICO: ¡Buenísimo! Anotamos la B1 — RC + incendio + robo.', 'COTIZADOR', '2026-10-08', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Coberturas de auto explicadas según el manual de Triunfo', 'Cada cobertura de auto dice qué incluye y qué no incluye según el manual de productos de Triunfo, y solo se ofrecen las coberturas cuyo contenido está confirmado.', 'Algunas coberturas se ofrecían con descripciones incompletas o prometían cosas que el plan no incluía.', 'El bot y la web describen cada cobertura con lo que realmente incluye y lo que no, y si el cliente pregunta por una cobertura ya cotizada, le explica la diferencia sin volver a cotizar.', NULL, 'COTIZADOR', '2026-10-09', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Si Triunfo no tiene los documentos, el pedido pasa a la oficina', 'Cuando un cliente pide la documentación de una póliza y Triunfo no la tiene disponible, el bot se lo avisa y le deja el pedido a un asesor.', 'El cliente se quedaba sin los documentos y sin saber qué hacer.', 'El bot le dice que no tiene los documentos en ese momento y que un asesor se los va a enviar, y el pedido aparece en el panel.', 'NICO: No tengo los documentos de esa póliza para enviarte ahora. Ya le pasé el pedido a un asesor para que te los mande (lunes a viernes de 8 a 16 hs).', 'BOT', '2026-10-08', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Contratar desde la cotización, con fotos de la documentación', 'Si el cliente elige una cobertura, el bot anota el pedido para un asesor y le pide las fotos del DNI y de la tarjeta del vehículo, que quedan adjuntas al pedido.', 'Después de cotizar, el cliente tenía que escribir de nuevo para contratar y pasar los papeles por otro lado.', 'El cliente elige la cobertura, manda las fotos paso a paso y un asesor recibe el pedido completo para terminar la contratación.', 'Cliente: B1
NICO: ¡Buenísimo! Para avanzar con la contratación necesito unas fotos 📸. Empecemos: mandame una foto del frente de tu DNI.', 'BOT', '2026-09-30', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
